------MultipartBoundary--usuoNszBLmv828mP55ddQCsMgl60IxvwtufBty14HX----
Content-Type: text/css
Content-Transfer-Encoding: binary
Content-Location: https://security.samsungmobile.com/css/common.css

@charset "utf-8";

@font-face { font-family: SamsungSharpSans; font-weight: 600; src: url("../font/SamsungSharpSans-Bold.woff") format("woff"); font-style: normal; }

@font-face { font-family: SamsungOne; font-weight: 400; src: url("../font/SamsungOne-400.woff") format("woff"), url("../font/SamsungOne-400_v1.0.ttf") format("truetype"); }

@font-face { font-family: SamsungOne; font-weight: 700; src: url("../font/SamsungOne-700.woff") format("woff"), url("../font/SamsungOne-700_v1.0.ttf") format("truetype"); }

@font-face { font-family: SamsungOne; font-weight: 800; src: url("../font/SamsungOne-800.woff") format("woff"), url("../font/SamsungOne-800_v1.0.ttf") format("truetype"); }

@font-face { font-family: SamsungOneKorea; font-weight: 400; src: url("../font/SamsungOneKorea-400.woff") format("woff"), url("../font/SamsungOneKorea-400.ttf") format("truetype"); }

@font-face { font-family: SamsungOneKorea; font-weight: 500; src: url("../font/SamsungOneKorea-500.woff") format("woff"), url("../font/SamsungOneKorea-500.ttf") format("truetype"); }

@font-face { font-family: SamsungOneKorea; font-weight: 600; src: url("../font/SamsungOneKorea-600.woff") format("woff"), url("../font/SamsungOneKorea-600.ttf") format("truetype"); }

html, body { height: 100%; }

body, p, h1, h2, h3, h4, h5, h6, ul, ol, li, dl, dt, dd, table, th, td, form, fieldset, legend, input, textarea, button, select { margin: 0px; padding: 0px; }

input, textarea, select, button, table { font-size: 14px; }

dt, dd, th, td { line-height: 1.7em; font-weight: normal; text-align: left; }

td div { line-height: normal; }

img, fieldset { border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }

ul, ol { list-style: none; }

em, address { font-style: normal; }

a { color: rgb(0, 0, 0); text-decoration: none; }

td a { color: rgb(46, 125, 171); }

td a:hover { color: rgb(44, 98, 121); }

a:hover, a:active, a:focus { }

img { vertical-align: top; }

label input { margin-right: 3px; vertical-align: middle; }

td input, td select, td img { vertical-align: middle; }

caption, legend { width: 0px; height: 0px; overflow: hidden; text-indent: -9999px; }

article, aside, details, figcaption, figure, footer, header, hgroup, menu, nav, section { display: block; }

legend { display: none; }

ol, ul { list-style: none; }

table { border-collapse: collapse; border-spacing: 0px; }

body { font-family: SamsungOne, Arial, sans-serif; font-weight: 400; font-size: 15px; color: rgb(34, 34, 34); line-height: 1.2; }

#skipnav { position: fixed; z-index: 6000; left: 0px; top: 0px; width: 100%; }

#skipnav a { display: block; height: 1px; overflow: hidden; }

#skipnav a:focus, #skipnav a:active { width: 100%; height: 30px; color: rgb(255, 255, 255); font-weight: bold; line-height: 30px; text-align: center; text-decoration: underline; background-color: rgb(13, 45, 162); }

#wrap { position: relative; width: 100%; }

#header { z-index: 100; width: 100%; height: 98px; }

#header.newwin_header { height: 75px; background: rgb(255, 255, 255); }

#header .header_inner { position: relative; margin: 0px auto; max-width: 1440px; z-index: 500; }

.logo { position: absolute; top: 26px; left: 20px; }

.logo a { display: block; width: 222px; line-height: 1.2; overflow: hidden; font-size: 20px; color: rgb(0, 0, 0); font-weight: 700; font-family: SamsungSharpSans; cursor: pointer; }

.logo.turkey_logo a { width: 360px; }

.logo a strong { display: block; }

#header.newwin_header .logo { top: 12px; }

.gnb { float: right; margin-top: 46px; margin-right: 20px; }

.menu { float: left; }

.menu > li { position: relative; float: left; padding-left: 36px; }

.menu > li:first-child { padding-left: 0px; }

.menu > li a { position: relative; font-weight: 700; font-size: 17px; color: rgb(0, 0, 0); }

.menu > li a:hover, .menu > li a:focus, .menu > li a:active, .menu > li a.on:hover, .menu > li a.on:focus, .menu > li a.on:active { color: rgb(0, 92, 195); }

.menu > li a.on { color: rgb(34, 34, 34); }

.menu > li > a { padding: 0px 10px; }

.menu > li > a.on::after { content: ""; display: inline-block; position: absolute; top: 50px; left: 0px; height: 3px; width: 100%; background-color: rgb(10, 124, 212); }

.submenu_bar { z-index: 100; display: none; position: absolute; left: 0px; right: 0px; top: 98px; height: 180px; border-top: 1px solid rgb(230, 230, 230); border-bottom: 1px solid rgb(230, 230, 230); background: rgb(255, 255, 255); }

.submenu { z-index: 101; display: none; position: absolute; padding: 50px 0px 30px 36px; left: 0px; right: 0px; }

.menu > li:first-child .submenu { padding-left: 0px; }

.submenu > li { display: block; margin-top: 10px; }

.submenu > li a { position: relative; display: block; text-align: center; font-weight: 400; line-height: 1.7; font-size: 15px; color: rgb(0, 0, 0); }

.submenu > li a:hover, .submenu > li a:focus, .submenu > li a:active, .submenu > li a.on:hover, .submenu > li a.on:focus, .submenu > li a.on:active { color: rgb(0, 92, 195); }

.menu_fix .submenu_bar { position: fixed; top: 62px; height: 180px !important; background-color: rgba(23, 23, 23, 0.8) !important; }

.menu_fix .submenu { padding: 30px 0px 30px 90px; }

.menu_fix .menu > li:first-child .submenu { padding-left: 0px; }

.menu_fix .submenu > li { display: block; margin-top: 10px; }

.toplink { float: left; }

.t_btn_login { display: inline-block; margin-left: 70px; margin-top: -4px; }

.t_btn_login a { display: inline-block; width: 82px; height: 26px; overflow: hidden; background-color: rgb(17, 70, 211); color: rgb(255, 255, 255); font-size: 14px; text-align: center; line-height: 26px; }

.t_btn_login a:hover, .t_btn_login a:focus, .t_btn_login a:active { text-decoration: underline; }

.menu_fix { position: fixed; top: 0px; z-index: 900; height: 62px !important; background-color: rgba(23, 23, 23, 0.8) !important; }

.menu_fix li a.on::after { content: ""; display: inline-block; position: absolute; top: 23px; height: 2px; background-color: rgb(241, 241, 241); }

.menu_fix .logo { display: none; }

.menu_fix .gnb { margin-top: 20px; clear: both; }

.menu_fix .gnb .menu { position: absolute; top: 20px; left: 50%; margin-left: -480px; }

.menu_fix .gnb .menu > li { padding-left: 90px; }

.menu_fix .gnb .menu > li:first-child { padding-left: 0px; }

.menu_fix .gnb .menu > li a { color: rgb(255, 255, 255); }

.menu_fix .gnb .menu > li a:hover, .menu_fix .gnb .menu > li a:focus { color: rgb(255, 255, 255); text-decoration: underline; }

.menu_fix .t_btn_login { display: none; }

.wrap_personal { float: left; position: relative; margin-left: 67px; margin-top: 0px; }

.wrap_personal .box { border-bottom: 1px solid rgb(150, 150, 151); padding-bottom: 7px; min-height: 24px; box-sizing: border-box; }

.wrap_personal .box li { display: table-cell; padding-right: 10px; background: url("../images/common/arw_personal.png") 100% 50% no-repeat; }

.wrap_personal .txt_id { display: inline-block; width: 130px; font-size: 12px; color: rgb(0, 0, 0); line-height: 1.2; padding: 0px 5px 0px 24px; vertical-align: middle; background: url("../images/common/ico_personal.png") 0px 45% no-repeat; word-break: break-all; font-weight: 700; letter-spacing: -0.01em; }

.menu_fix .wrap_personal { margin-top: 0px; margin-right: 20px; }

.menu_fix .box { border-bottom: 1px solid rgb(124, 126, 127); }

.menu_fix .txt_id { color: rgb(255, 255, 255); font-weight: 400; background: url("../images/common/ico_personal2.png") 0px 45% no-repeat; }

.menu_fix .box li { background: url("../images/common/arw_personal2.png") 100% 50% no-repeat; }

.wrap_personal .personal_box { position: absolute; right: 0px; margin-top: -5px; width: 169px; background-color: rgb(0, 0, 0); padding: 11px 13px; box-sizing: border-box; display: none; }

.personal_box a { position: relative; display: block; color: rgb(255, 255, 255); font-size: 12px; letter-spacing: 0.05em; padding-bottom: 9px; }

.personal_box li:last-child a { padding-bottom: 0px; }

.personal_box a:hover, .personal_box a:focus, .personal_box a:active { text-decoration: underline; }

.personal_box a em { color: rgb(255, 243, 48); text-decoration: underline; padding-left: 1px; font-weight: bold; }

.personal_box a::after { content: ""; display: block; position: absolute; top: 3px; right: 0px; width: 4px; height: 8px; background: url("../images/common/bg_personal_arw.png") 0px 0px no-repeat; }

.personal_box a:hover::after, .personal_box a:focus::after, .personal_box a:active::after { background: url("../images/common/bg_personal_arw.png") 0px 100% no-repeat; }

.gnb::after { content: ""; display: block; clear: both; }

.personal_menu { display: inline-block; }

#header .header_inner, .breadcrumb ul, #container h2.page_tit, #footer .in, .wrap_sub_menu { max-width: 1440px; }

.wrap_search { position: relative; float: right; width: 36px; height: 36px; margin-left: 20px; }

.open_search, .btn_search { display: inline-block; overflow: hidden; position: absolute; top: -10px; right: 0px; width: 36px; height: 36px; text-indent: -9999em; background: url("../images/common/ico_search.png") 50% 50% no-repeat; }

.menu_fix .open_search { top: -7px; background: url("../images/common/ico_search_white.png") 50% 50% no-repeat; }

.close_search { overflow: hidden; position: absolute; top: -10px; right: 0px; width: 45px; height: 39px; text-indent: -9999em; background: url("../images/common/ico_search_close.png") 50% 50% no-repeat rgb(39, 39, 39); }

.menu_fix .close_search { position: absolute; top: -20px; right: 1px; width: 61px; height: 61px; background-color: rgb(17, 70, 212); }

.wrap_input { position: absolute; top: 29px; right: 0px; width: 425px; height: 52px; background: rgb(255, 255, 255); border: 1px solid rgb(83, 83, 83); box-shadow: rgba(0, 0, 0, 0.35) 10px 8px 24px -4px; }

.menu_fix .wrap_input { top: 41px; }

.wrap_input input { border-width: medium; border-style: none; border-color: currentcolor; border-image: none; width: calc(100% - 39px); height: 52px; line-height: 52px; padding-left: 12px; vertical-align: top; box-sizing: border-box; }

.wrap_input .btn_search { height: 52px; width: 39px; top: 0px; right: 0px; }

#container { width: 100%; margin-bottom: 30px; position: relative; overflow: hidden; }

